<?php
declare(strict_types=1);
header('X-Content-Type-Options: nosniff'); header('Referrer-Policy: no-referrer');
$envFile=__DIR__.'/.env';
if(!is_file($envFile)){http_response_code(503);exit('DCP Cloud is not configured. Copy .env.example to .env and configure the database.');}
foreach(file($envFile, FILE_IGNORE_NEW_LINES|FILE_SKIP_EMPTY_LINES) as $line){$line=trim($line);if($line===''||$line[0]==='#'||!str_contains($line,'='))continue;[$k,$v]=explode('=',$line,2);putenv(trim($k).'='.trim($v," \\t\\n\\r\\0\\x0B\\\"'"));}
function db():PDO{static $pdo=null;if($pdo)return $pdo;$dsn='mysql:host='.getenv('DB_HOST').';port='.(getenv('DB_PORT')?:3306).';dbname='.getenv('DB_NAME').';charset=utf8mb4';return $pdo=new PDO($dsn,(string)getenv('DB_USER'),(string)getenv('DB_PASSWORD'),[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);}
function reply(int $status,array $data):never{http_response_code($status);header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');echo json_encode($data,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);exit;}
function input():array{$v=json_decode(file_get_contents('php://input')?:'{}',true);return is_array($v)?$v:reply(400,['error'=>'invalid_json']);}
function uuid():string{$b=random_bytes(16);$b[6]=chr((ord($b[6])&15)|64);$b[8]=chr((ord($b[8])&63)|128);$h=bin2hex($b);return substr($h,0,8).'-'.substr($h,8,4).'-'.substr($h,12,4).'-'.substr($h,16,4).'-'.substr($h,20);}
function hash_token(string $t):string{return hash_hmac('sha256',$t,(string)getenv('APP_KEY'));}
function bearer():string{$h=$_SERVER['HTTP_AUTHORIZATION']??'';return preg_match('/^Bearer\s+(.+)$/i',$h,$m)?trim($m[1]):'';}
function auth_user():array{$t=bearer();if(strlen($t)<40)reply(401,['error'=>'unauthorized']);$q=db()->prepare('SELECT u.* FROM api_tokens a JOIN users u ON u.id=a.user_id WHERE a.token_hash=? AND a.expires_at>NOW()');$q->execute([hash_token($t)]);$u=$q->fetch();if(!$u)reply(401,['error'=>'unauthorized']);return $u;}
function auth_device():array{$t=bearer();if(strlen($t)<40)reply(401,['error'=>'unauthorized']);$q=db()->prepare('SELECT * FROM devices WHERE token_hash=? AND revoked_at IS NULL');$q->execute([hash_token($t)]);$d=$q->fetch();if(!$d)reply(401,['error'=>'unauthorized']);db()->prepare('UPDATE devices SET last_seen_at=NOW() WHERE id=?')->execute([$d['id']]);return $d;}
function issue_user_token(int $uid):string{$t=bin2hex(random_bytes(32));db()->prepare('INSERT INTO api_tokens(user_id,token_hash,expires_at) VALUES(?,?,DATE_ADD(NOW(),INTERVAL 30 DAY))')->execute([$uid,hash_token($t)]);return $t;}
$method=$_SERVER['REQUEST_METHOD']??'GET';$path=parse_url($_SERVER['REQUEST_URI']??'/',PHP_URL_PATH)?:'/';
if($path==='/'&&$method==='GET'){require __DIR__.'/site.php';exit;}
if($path==='/api/v1/health'&&$method==='GET')reply(200,['ok'=>true,'service'=>'DCP Cloud','relay'=>false,'transport'=>'signaling-only']);
if($path==='/api/v1/register'&&$method==='POST'){$b=input();$email=strtolower(trim((string)($b['email']??'')));$pass=(string)($b['password']??'');$name=trim((string)($b['display_name']??'DCP User'));if(!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<12||strlen($pass)>200)reply(422,['error'=>'valid_email_and_password_12_chars_required']);try{db()->prepare('INSERT INTO users(email,password_hash,display_name) VALUES(?,?,?)')->execute([$email,password_hash($pass,PASSWORD_DEFAULT),mb_substr($name,0,120)]);}catch(PDOException $e){if($e->getCode()==='23000')reply(409,['error'=>'email_already_registered']);throw $e;}$uid=(int)db()->lastInsertId();reply(201,['user_id'=>$uid,'access_token'=>issue_user_token($uid),'token_expires_days'=>30]);}
if($path==='/api/v1/login'&&$method==='POST'){$b=input();$q=db()->prepare('SELECT * FROM users WHERE email=?');$q->execute([strtolower(trim((string)($b['email']??'')))]);$u=$q->fetch();if(!$u||!password_verify((string)($b['password']??''),$u['password_hash']))reply(401,['error'=>'invalid_credentials']);reply(200,['access_token'=>issue_user_token((int)$u['id']),'token_expires_days'=>30]);}
if($path==='/api/v1/devices/register'&&$method==='POST'){$u=auth_user();$b=input();$id=uuid();$token=bin2hex(random_bytes(32));db()->prepare('INSERT INTO devices(id,user_id,label,platform,token_hash,last_seen_at) VALUES(?,?,?,?,?,NOW())')->execute([$id,$u['id'],mb_substr(trim((string)($b['label']??'DCP Device')),0,120),mb_substr((string)($b['platform']??'unknown'),0,40),hash_token($token)]);reply(201,['device_id'=>$id,'device_token'=>$token,'heartbeat_seconds'=>30]);}
if($path==='/api/v1/devices'&&$method==='GET'){$u=auth_user();$q=db()->prepare('SELECT id,label,platform,last_seen_at,IF(last_seen_at>DATE_SUB(NOW(),INTERVAL 90 SECOND),1,0) online FROM devices WHERE user_id=? AND revoked_at IS NULL ORDER BY label');$q->execute([$u['id']]);reply(200,['devices'=>$q->fetchAll()]);}
if(preg_match('#^/api/v1/devices/([a-f0-9-]{36})/revoke$#',$path,$m)&&$method==='POST'){$u=auth_user();$s=db()->prepare('UPDATE devices SET revoked_at=NOW() WHERE id=? AND user_id=?');$s->execute([$m[1],$u['id']]);reply($s->rowCount()?200:404,['revoked'=>(bool)$s->rowCount()]);}
if($path==='/api/v1/devices/heartbeat'&&$method==='POST'){$d=auth_device();reply(200,['ok'=>true,'device_id'=>$d['id'],'server_time'=>gmdate('c')]);}
if($path==='/api/v1/connections/request'&&$method==='POST'){$d=auth_device();$b=input();$target=(string)($b['target_device']??'');$q=db()->prepare('SELECT id,user_id FROM devices WHERE id=? AND revoked_at IS NULL');$q->execute([$target]);$peer=$q->fetch();if(!$peer||$peer['user_id']!=$d['user_id'])reply(404,['error'=>'target_not_found']);$id=uuid();db()->prepare("INSERT INTO connection_requests(id,source_device,target_device,status,expires_at) VALUES(?,?,?,'pending',DATE_ADD(NOW(),INTERVAL 90 SECOND))")->execute([$id,$d['id'],$target]);reply(201,['request_id'=>$id,'expires_in'=>90]);}
if(preg_match('#^/api/v1/connections/([a-f0-9-]{36})/signal$#',$path,$m)&&$method==='POST'){$d=auth_device();$b=input();$payload=(string)($b['envelope']??'');if($payload===''||strlen($payload)>32768)reply(422,['error'=>'invalid_envelope']);$q=db()->prepare('SELECT r.source_device,r.target_device FROM connection_requests r JOIN devices a ON a.id=r.source_device JOIN devices z ON z.id=r.target_device WHERE r.id=? AND r.expires_at>NOW() AND a.revoked_at IS NULL AND z.revoked_at IS NULL AND a.user_id=z.user_id');$q->execute([$m[1]]);$c=$q->fetch();if(!$c||!in_array($d['id'],[$c['source_device'],$c['target_device']],true))reply(404,['error'=>'request_not_found']);$to=$d['id']===$c['source_device']?$c['target_device']:$c['source_device'];db()->prepare('INSERT INTO signaling_messages(request_id,sender_device,recipient_device,envelope,expires_at) VALUES(?,?,?,?,DATE_ADD(NOW(),INTERVAL 180 SECOND))')->execute([$m[1],$d['id'],$to,$payload]);reply(202,['accepted'=>true,'delivery'=>'signaling_only']);}
if(preg_match('#^/api/v1/connections/([a-f0-9-]{36})/signals$#',$path,$m)&&$method==='GET'){$d=auth_device();$after=max(0,(int)($_GET['after']??0));$s=db()->prepare('SELECT id,sender_device,envelope,created_at FROM signaling_messages WHERE request_id=? AND recipient_device=? AND id>? AND expires_at>NOW() ORDER BY id LIMIT 50');$s->execute([$m[1],$d['id'],$after]);reply(200,['signals'=>$s->fetchAll()]);}
reply(404,['error'=>'not_found']);
